CREATE TABLE applicants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_ref text UNIQUE NOT NULL, full_name text NOT NULL, national_id text NOT NULL, phone text NOT NULL, email text NOT NULL, home_county text NOT NULL, preferred_branch_county text NOT NULL, applied_position text NOT NULL, status text NOT NULL DEFAULT 'submitted', requires_relocation boolean NOT NULL DEFAULT false, applied_at timestamptz NOT NULL DEFAULT now(), selected_cost_item_ids jsonb NOT NULL DEFAULT '[]'::jsonb, total_amount_kes integer NOT NULL DEFAULT 0, payment_status text NOT NULL DEFAULT 'unpaid')